-- Tapd In: inbox digest. Messages (email, later texts) are sorted into the
-- owner's categories and summarized. Run in the Supabase SQL editor after
-- 0016_entry_replies.sql. Purely additive: nothing existing is changed except
-- one new column on public.users.

-- Off by default. Only accounts switched on see the inbox section.
alter table public.users
  add column if not exists inbox_enabled boolean not null default false;

-- Random, unguessable part of this owner's forwarding address
-- (<token>@inbox.tapdin.tech). Anyone who knows it can add mail to the inbox,
-- so it is generated by the server and never shown to anyone else.
alter table public.users
  add column if not exists inbox_token text unique;

-- The buckets an owner wants their messages sorted into, e.g. Clients, Deals.
create table if not exists public.inbox_categories (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.users(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 60),
  -- Plain-language hint for the AI: what belongs here.
  description text check (description is null or char_length(description) <= 300),
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists inbox_categories_owner
  on public.inbox_categories (owner_id, sort_order);

-- One row per incoming message. Only the summary is kept long term: raw_text
-- holds the message just long enough to be processed and is then cleared.
create table if not exists public.inbox_messages (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.users(id) on delete cascade,
  source text not null check (source in ('forward', 'gmail', 'microsoft', 'imap', 'sms')),
  -- Provider's id for the message, so the same one is never added twice.
  external_id text not null,
  sender_name text,
  sender_address text,
  subject text,
  received_at timestamptz not null,
  raw_text text,
  -- Mail headers used to spot newsletters and automated mail.
  headers jsonb,
  status text not null default 'pending'
    check (status in ('pending', 'processed', 'skipped', 'failed')),
  skip_reason text,
  category_id uuid references public.inbox_categories(id) on delete set null,
  summary text,
  importance text check (importance in ('urgent', 'normal', 'low')),
  attempts integer not null default 0,
  created_at timestamptz not null default now(),
  processed_at timestamptz,
  unique (owner_id, source, external_id)
);

create index if not exists inbox_messages_pending
  on public.inbox_messages (created_at)
  where status = 'pending';

create index if not exists inbox_messages_owner_received
  on public.inbox_messages (owner_id, received_at desc);

alter table public.inbox_categories enable row level security;
alter table public.inbox_messages enable row level security;

-- Owners manage their own categories and can read their own messages.
-- Messages are written and processed only by the server (service role).
create policy "owners manage own inbox categories"
  on public.inbox_categories for all
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy "owners read own inbox messages"
  on public.inbox_messages for select
  using (owner_id = auth.uid());

-- Which weekly updates have gone out, so one is never sent twice.
create table if not exists public.inbox_digests (
  owner_id uuid not null references public.users(id) on delete cascade,
  week_start date not null,
  sent_at timestamptz not null default now(),
  primary key (owner_id, week_start)
);

alter table public.inbox_digests enable row level security;
